const iPlay = (<svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"/></svg>);
const iPause = (<svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/></svg>);
const iArrow = (<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>);
const iDl = (<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>);

function Waveform({ playing }) {
  const hts = [8,14,20,12,24,18,10,22,16,8,20,14,10,18,24,12,16,8,20,14];
  return (
    <div className="podcast-waveform">
      {hts.map((h,i) => (
        <div key={i} className="waveform-bar" style={{
          height: h,
          animationName: playing ? "wavePlay" : "none",
          animationDuration: `${0.4+(i%5)*0.1}s`,
          animationTimingFunction: "ease-in-out",
          animationIterationCount: "infinite",
          animationDelay: `${i*0.04}s`,
        }} />
      ))}
    </div>
  );
}

